CREATE TABLE IF NOT EXISTS institutions(id TEXT PRIMARY KEY,name TEXT NOT NULL,settings JSONB NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,tenant TEXT NOT NULL REFERENCES institutions(id),name TEXT NOT NULL,email TEXT NOT NULL,password TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('ADMIN','CHAIRPERSON','SECRETARY','MEMBER','VIEWER')),department TEXT NOT NULL DEFAULT '',skills TEXT NOT NULL DEFAULT '',gender TEXT NOT NULL DEFAULT 'Unspecified',available BOOLEAN NOT NULL DEFAULT true,active BOOLEAN NOT NULL DEFAULT true,session_version INT NOT NULL DEFAULT 0, UNIQUE(tenant,email));
CREATE TABLE IF NOT EXISTS committees(id TEXT PRIMARY KEY,tenant TEXT NOT NULL REFERENCES institutions(id),name TEXT NOT NULL,type TEXT NOT NULL,tor TEXT NOT NULL,skills TEXT NOT NULL DEFAULT '',seats INT NOT NULL CHECK(seats BETWEEN 1 AND 50),term_months INT NOT NULL CHECK(term_months BETWEEN 1 AND 120),max_terms INT NOT NULL DEFAULT 2,quorum_count INT NOT NULL DEFAULT 1 CHECK(quorum_count>=1 AND quorum_count<=seats),status TEXT NOT NULL DEFAULT 'ACTIVE',parent_id TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
ALTER TABLE committees ADD COLUMN IF NOT EXISTS quorum_count INT NOT NULL DEFAULT 1 CHECK(quorum_count>=1 AND quorum_count<=seats);
CREATE TABLE IF NOT EXISTS conflicts(id TEXT PRIMARY KEY,tenant TEXT NOT NULL,user_id TEXT NOT NULL REFERENCES users(id),committee_id TEXT NOT NULL REFERENCES committees(id),description TEXT NOT NULL,active BOOLEAN NOT NULL DEFAULT true,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS allocations(id TEXT PRIMARY KEY,tenant TEXT NOT NULL,user_id TEXT NOT NULL REFERENCES users(id),committee_id TEXT NOT NULL REFERENCES committees(id),role TEXT NOT NULL,start_date DATE NOT NULL,end_date DATE NOT NULL,status TEXT NOT NULL CHECK(status IN ('PENDING','REVIEWED','ACTIVE','REJECTED','ENDED')),score JSONB NOT NULL,proposed_by TEXT NOT NULL REFERENCES users(id),reviewed_by TEXT REFERENCES users(id),approved_by TEXT REFERENCES users(id),reason TEXT NOT NULL DEFAULT '',CHECK(end_date>start_date));
CREATE TABLE IF NOT EXISTS meetings(id TEXT PRIMARY KEY,tenant TEXT NOT NULL,committee_id TEXT NOT NULL REFERENCES committees(id),title TEXT NOT NULL,starts_at TIMESTAMPTZ NOT NULL,venue TEXT NOT NULL,agenda TEXT NOT NULL,minutes TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'SCHEDULED',approved_by TEXT REFERENCES users(id),submitted_by TEXT REFERENCES users(id),created_by TEXT NOT NULL REFERENCES users(id));
ALTER TABLE meetings ADD COLUMN IF NOT EXISTS submitted_by TEXT REFERENCES users(id);
CREATE TABLE IF NOT EXISTS attendance(tenant TEXT NOT NULL,meeting_id TEXT NOT NULL REFERENCES meetings(id),user_id TEXT NOT NULL REFERENCES users(id),present BOOLEAN NOT NULL,PRIMARY KEY(meeting_id,user_id));
CREATE TABLE IF NOT EXISTS actions(id TEXT PRIMARY KEY,tenant TEXT NOT NULL,meeting_id TEXT NOT NULL REFERENCES meetings(id),title TEXT NOT NULL,owner_id TEXT NOT NULL REFERENCES users(id),due_date DATE NOT NULL,status TEXT NOT NULL DEFAULT 'OPEN');
CREATE TABLE IF NOT EXISTS votes(id TEXT PRIMARY KEY,tenant TEXT NOT NULL,meeting_id TEXT NOT NULL REFERENCES meetings(id),question TEXT NOT NULL,closes_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS ballots(tenant TEXT NOT NULL,vote_id TEXT NOT NULL REFERENCES votes(id),user_id TEXT NOT NULL REFERENCES users(id),choice TEXT NOT NULL CHECK(choice IN ('YES','NO','ABSTAIN')),PRIMARY KEY(vote_id,user_id));
CREATE TABLE IF NOT EXISTS documents(id TEXT PRIMARY KEY,tenant TEXT NOT NULL,committee_id TEXT NOT NULL REFERENCES committees(id),title TEXT NOT NULL,version INT NOT NULL,access TEXT NOT NULL CHECK(access IN ('STANDARD','CONFIDENTIAL')),filename TEXT NOT NULL,stored_name TEXT NOT NULL,mime TEXT NOT NULL,uploaded_by TEXT NOT NULL REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(committee_id,title,version));
CREATE TABLE IF NOT EXISTS notifications(id TEXT PRIMARY KEY,tenant TEXT NOT NULL,user_id TEXT NOT NULL REFERENCES users(id),title TEXT NOT NULL,body TEXT NOT NULL,read BOOLEAN NOT NULL DEFAULT false,dedupe TEXT UNIQUE,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS outbox(id TEXT PRIMARY KEY,tenant TEXT NOT NULL,recipient TEXT NOT NULL,subject TEXT NOT NULL,body TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'QUEUED',attempts INT NOT NULL DEFAULT 0,next_attempt TIMESTAMPTZ NOT NULL DEFAULT now(),last_error TEXT NOT NULL DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit(id TEXT PRIMARY KEY,tenant TEXT NOT NULL,user_id TEXT NOT NULL,action TEXT NOT NULL,entity TEXT NOT NULL,details JSONB NOT NULL,ip TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE OR REPLACE FUNCTION protect_audit() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Audit records are append-only'; END; $$;
DROP TRIGGER IF EXISTS audit_immutable ON audit;
CREATE TRIGGER audit_immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON audit FOR EACH STATEMENT EXECUTE FUNCTION protect_audit();
CREATE INDEX IF NOT EXISTS allocation_tenant ON allocations(tenant,committee_id,status);
CREATE INDEX IF NOT EXISTS notification_user ON notifications(tenant,user_id);
CREATE INDEX IF NOT EXISTS audit_tenant ON audit(tenant,created_at);
-- Governance release: additive migrations preserve existing records.
ALTER TABLE committees ADD COLUMN IF NOT EXISTS allocation_policy JSONB NOT NULL DEFAULT '{}';
ALTER TABLE committees ADD COLUMN IF NOT EXISTS policy_version INT NOT NULL DEFAULT 1;
CREATE TABLE IF NOT EXISTS policy_history(id TEXT PRIMARY KEY,tenant TEXT NOT NULL,committee_id TEXT NOT NULL REFERENCES committees(id),version INT NOT NULL,policy JSONB NOT NULL,reason TEXT NOT NULL,changed_by TEXT NOT NULL REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(committee_id,version));
CREATE TABLE IF NOT EXISTS declaration_requests(id TEXT PRIMARY KEY,tenant TEXT NOT NULL,committee_id TEXT NOT NULL REFERENCES committees(id),user_id TEXT NOT NULL REFERENCES users(id),requested_by TEXT NOT NULL REFERENCES users(id),status TEXT NOT NULL DEFAULT 'REQUESTED',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(committee_id,user_id));
CREATE TABLE IF NOT EXISTS declarations(id TEXT PRIMARY KEY,tenant TEXT NOT NULL,committee_id TEXT NOT NULL REFERENCES committees(id),user_id TEXT NOT NULL REFERENCES users(id),kind TEXT NOT NULL CHECK(kind IN ('NO_CONFLICT','CONFLICT')),description TEXT NOT NULL,evidence TEXT NOT NULL,attested BOOLEAN NOT NULL CHECK(attested=true),status TEXT NOT NULL CHECK(status IN ('SUBMITTED','CLEARED','CONFLICT','RESOLVED','SUPERSEDED')),reviewed_by TEXT REFERENCES users(id),review_reason TEXT NOT NULL DEFAULT '',valid_until DATE NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS recusals(id TEXT PRIMARY KEY,tenant TEXT NOT NULL,meeting_id TEXT NOT NULL REFERENCES meetings(id),user_id TEXT NOT NULL REFERENCES users(id),reason TEXT NOT NULL,recorded_by TEXT NOT NULL REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(meeting_id,user_id));
CREATE TABLE IF NOT EXISTS checklist_items(id TEXT PRIMARY KEY,tenant TEXT NOT NULL,committee_id TEXT NOT NULL REFERENCES committees(id),title TEXT NOT NULL,requirement TEXT NOT NULL,policy_reference TEXT NOT NULL,due_date DATE,required BOOLEAN NOT NULL DEFAULT true,status TEXT NOT NULL DEFAULT 'OPEN' CHECK(status IN ('OPEN','SUBMITTED','VERIFIED','RETURNED')),evidence TEXT NOT NULL DEFAULT '',document_id TEXT REFERENCES documents(id),submitted_by TEXT REFERENCES users(id),reviewed_by TEXT REFERENCES users(id),review_reason TEXT NOT NULL DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS declarations_scope ON declarations(tenant,committee_id,user_id,created_at);
ALTER TABLE checklist_items ADD COLUMN IF NOT EXISTS allocation_id TEXT REFERENCES allocations(id);
ALTER TABLE checklist_items ADD COLUMN IF NOT EXISTS meeting_id TEXT REFERENCES meetings(id);

-- Access groups: additive upgrade; existing roles continue until a user is grouped.
CREATE TABLE IF NOT EXISTS access_groups(id TEXT PRIMARY KEY,tenant TEXT NOT NULL REFERENCES institutions(id),name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',enabled BOOLEAN NOT NULL DEFAULT true,all_committees BOOLEAN NOT NULL DEFAULT false,committee_ids JSONB NOT NULL DEFAULT '[]',permissions JSONB NOT NULL DEFAULT '[]',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(tenant,name));
CREATE TABLE IF NOT EXISTS access_group_members(tenant TEXT NOT NULL REFERENCES institutions(id),group_id TEXT NOT NULL REFERENCES access_groups(id),user_id TEXT NOT NULL REFERENCES users(id),PRIMARY KEY(group_id,user_id));
CREATE INDEX IF NOT EXISTS access_member_lookup ON access_group_members(tenant,user_id);

-- Notification centre: preferences, record links and delivery ownership.
ALTER TABLE users ADD COLUMN IF NOT EXISTS notification_preferences JSONB NOT NULL DEFAULT '{}';
ALTER TABLE notifications ADD COLUMN IF NOT EXISTS category TEXT NOT NULL DEFAULT 'GENERAL';
ALTER TABLE notifications ADD COLUMN IF NOT EXISTS target_page TEXT;
ALTER TABLE notifications ADD COLUMN IF NOT EXISTS target_id TEXT;
ALTER TABLE notifications ADD COLUMN IF NOT EXISTS in_app BOOLEAN NOT NULL DEFAULT true;
ALTER TABLE notifications ADD COLUMN IF NOT EXISTS archived BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE outbox ADD COLUMN IF NOT EXISTS user_id TEXT REFERENCES users(id);
ALTER TABLE outbox ADD COLUMN IF NOT EXISTS notification_id TEXT REFERENCES notifications(id);
CREATE INDEX IF NOT EXISTS notification_inbox ON notifications(tenant,user_id,created_at);
ALTER TABLE outbox ADD COLUMN IF NOT EXISTS claimed_at TIMESTAMPTZ;

CREATE TABLE IF NOT EXISTS template_records(id TEXT PRIMARY KEY,tenant TEXT NOT NULL REFERENCES institutions(id),kind TEXT NOT NULL,record_id TEXT NOT NULL,committee_id TEXT NOT NULL REFERENCES committees(id),sequence INT NOT NULL,reference TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(tenant,kind,record_id),UNIQUE(tenant,sequence));

CREATE TABLE IF NOT EXISTS report_schedules(id TEXT PRIMARY KEY,tenant TEXT NOT NULL REFERENCES institutions(id),name TEXT NOT NULL,report_type TEXT NOT NULL,format TEXT NOT NULL,committee_id TEXT REFERENCES committees(id),recipient_ids JSONB NOT NULL,frequency TEXT NOT NULL,time TEXT NOT NULL,weekday INT NOT NULL,monthday INT NOT NULL,enabled BOOLEAN NOT NULL DEFAULT true,next_run TIMESTAMPTZ NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),version INT NOT NULL DEFAULT 1,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS report_deliveries(id TEXT PRIMARY KEY,tenant TEXT NOT NULL REFERENCES institutions(id),schedule_id TEXT NOT NULL REFERENCES report_schedules(id),user_id TEXT NOT NULL REFERENCES users(id),run_key TEXT NOT NULL,configuration JSONB NOT NULL,manual BOOLEAN NOT NULL DEFAULT false,status TEXT NOT NULL DEFAULT 'QUEUED',attempts INT NOT NULL DEFAULT 0,last_error TEXT NOT NULL DEFAULT '',next_attempt TIMESTAMPTZ NOT NULL DEFAULT now(),claimed_at TIMESTAMPTZ,sent_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(schedule_id,user_id,run_key));
CREATE TABLE IF NOT EXISTS password_resets(id TEXT PRIMARY KEY,tenant TEXT NOT NULL REFERENCES institutions(id),user_id TEXT NOT NULL REFERENCES users(id),token_hash TEXT NOT NULL UNIQUE,session_version INT NOT NULL,expires_at TIMESTAMPTZ NOT NULL,used BOOLEAN NOT NULL DEFAULT false,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS password_resets_user_created ON password_resets(user_id,created_at DESC);
